"""Run SQL SELECT queries against CSV files. See SPEC.md."""

import csv
import decimal
import functools
import os
import re

__all__ = ["QueryError", "Result", "run"]


class QueryError(Exception):
    """Raised for any problem with a query."""


class Result:
    """The result of a query: ``columns`` (names) and ``rows`` (tuples)."""

    def __init__(self, columns, rows):
        self.columns = columns
        self.rows = rows

    def __repr__(self):
        return "Result(columns=%r, rows=%r)" % (self.columns, self.rows)

    def __eq__(self, other):
        if not isinstance(other, Result):
            return NotImplemented
        return self.columns == other.columns and self.rows == other.rows


def run(sql, directory="."):
    """Run ``sql`` against the CSV files in ``directory``."""
    if not isinstance(sql, str):
        raise QueryError("query must be a string")
    query = _Parser(_tokenize(sql), sql).parse_query()
    return _execute(query, directory)


# ---------------------------------------------------------------------------
# Lexer

KEYWORDS = {
    "SELECT", "DISTINCT", "FROM", "WHERE", "GROUP", "BY", "HAVING", "ORDER",
    "ASC", "DESC", "LIMIT", "OFFSET", "AS", "AND", "OR", "NOT", "IS", "NULL",
    "IN", "BETWEEN", "LIKE", "TRUE", "FALSE",
}

_NUMBER_RE = re.compile(r"[0-9]+\.[0-9]*|\.[0-9]+|[0-9]+")
_NAME_RE = re.compile(r"[^\W\d]\w*")
_OPERATORS = ("<=", ">=", "<>", "!=", "||", "=", "<", ">", "+", "-", "*",
              "/", "(", ")", ",", ";")


class _Token:
    __slots__ = ("kind", "value", "start", "end")

    def __init__(self, kind, value, start, end):
        # kind is one of: kw, name, int, float, str, op, eof
        self.kind = kind
        self.value = value
        self.start = start
        self.end = end

    def describe(self):
        if self.kind == "eof":
            return "end of query"
        if self.kind == "str":
            return "string literal"
        return repr(str(self.value))


def _read_quoted(sql, pos, quote):
    """Read a quoted string starting at ``pos``; return (text, end)."""
    parts = []
    i = pos + 1
    while True:
        j = sql.find(quote, i)
        if j < 0:
            what = "string" if quote == "'" else "quoted name"
            raise QueryError("unterminated %s at position %d" % (what, pos))
        parts.append(sql[i:j])
        if sql.startswith(quote, j + 1):
            parts.append(quote)
            i = j + 2
        else:
            return "".join(parts), j + 1


def _tokenize(sql):
    tokens = []
    pos = 0
    n = len(sql)
    while pos < n:
        ch = sql[pos]
        if ch.isspace():
            pos += 1
            continue
        if ch == "'":
            text, end = _read_quoted(sql, pos, "'")
            tokens.append(_Token("str", text, pos, end))
            pos = end
            continue
        if ch == '"':
            text, end = _read_quoted(sql, pos, '"')
            tokens.append(_Token("name", text, pos, end))
            pos = end
            continue
        m = _NUMBER_RE.match(sql, pos)
        if m:
            end = m.end()
            if end < n and (sql[end].isalnum() or sql[end] in "_."):
                raise QueryError("invalid number at position %d" % pos)
            text = m.group()
            if "." in text:
                tokens.append(_Token("float", float(text), pos, end))
            else:
                tokens.append(_Token("int", int(text), pos, end))
            pos = end
            continue
        m = _NAME_RE.match(sql, pos)
        if m:
            word = m.group()
            if word.upper() in KEYWORDS:
                tokens.append(_Token("kw", word.upper(), pos, m.end()))
            else:
                tokens.append(_Token("name", word, pos, m.end()))
            pos = m.end()
            continue
        for op in _OPERATORS:
            if sql.startswith(op, pos):
                tokens.append(_Token("op", op, pos, pos + len(op)))
                pos += len(op)
                break
        else:
            raise QueryError("unexpected character %r at position %d"
                             % (ch, pos))
    tokens.append(_Token("eof", None, n, n))
    return tokens


# ---------------------------------------------------------------------------
# Parser
#
# Expressions are nested tuples, so they can be compared and hashed (GROUP BY
# matching relies on this):
#
#   ("lit", type_name, value)        ("name", text)  -> ("col", index)
#   ("neg", e)   ("not", e)          ("and", a, b)   ("or", a, b)
#   ("bin", op, a, b)                ("cmp", op, a, b)
#   ("isnull", e, negated)           ("in", e, items, negated)
#   ("between", e, lo, hi, negated)  ("like", e, pattern, negated)
#   ("func", NAME, args)             ("agg", NAME, arg_or_None)

SCALAR_ARITY = {
    "LOWER": (1, 1), "UPPER": (1, 1), "LENGTH": (1, 1), "ABS": (1, 1),
    "ROUND": (1, 2), "COALESCE": (1, None),
}
AGGREGATES = {"COUNT", "SUM", "AVG", "MIN", "MAX"}


def _lit(value):
    return ("lit", type(value).__name__, value)


class _Query:
    def __init__(self):
        self.distinct = False
        self.columns = None   # None for "*", else [(expr, alias, text, plain)]
        self.table = None
        self.where = None
        self.group_by = []
        self.having = None
        self.order_by = []    # [(item, descending)]
        self.limit = None
        self.offset = 0


class _Parser:
    def __init__(self, tokens, sql):
        self.tokens = tokens
        self.sql = sql
        self.i = 0

    # -- helpers

    @property
    def tok(self):
        return self.tokens[self.i]

    def advance(self):
        tok = self.tokens[self.i]
        self.i += 1
        return tok

    def at_kw(self, *words):
        return self.tok.kind == "kw" and self.tok.value in words

    def at_op(self, *ops):
        return self.tok.kind == "op" and self.tok.value in ops

    def accept_kw(self, word):
        if self.at_kw(word):
            return self.advance()
        return None

    def accept_op(self, op):
        if self.at_op(op):
            return self.advance()
        return None

    def error(self, expected):
        tok = self.tok
        raise QueryError("syntax error at position %d: expected %s, found %s"
                         % (tok.start, expected, tok.describe()))

    def expect_kw(self, word):
        if not self.at_kw(word):
            self.error(word)
        return self.advance()

    def expect_op(self, op):
        if not self.at_op(op):
            self.error(repr(op))
        return self.advance()

    def expect_name(self):
        if self.tok.kind != "name":
            self.error("a name")
        return self.advance().value

    def expect_int(self):
        if self.tok.kind != "int":
            self.error("an integer")
        return self.advance().value

    def text(self, start, stop):
        """Source text of tokens ``start`` up to (excluding) ``stop``."""
        return self.sql[self.tokens[start].start:self.tokens[stop - 1].end]

    # -- query

    def parse_query(self):
        q = _Query()
        self.expect_kw("SELECT")
        q.distinct = bool(self.accept_kw("DISTINCT"))
        if self.accept_op("*"):
            q.columns = None
        else:
            q.columns = [self.parse_column()]
            while self.accept_op(","):
                q.columns.append(self.parse_column())
        self.expect_kw("FROM")
        q.table = self.expect_name()
        if self.accept_kw("WHERE"):
            q.where = self.parse_expr()
        if self.accept_kw("GROUP"):
            self.expect_kw("BY")
            q.group_by = [self.parse_expr()]
            while self.accept_op(","):
                q.group_by.append(self.parse_expr())
        if self.accept_kw("HAVING"):
            q.having = self.parse_expr()
        if self.accept_kw("ORDER"):
            self.expect_kw("BY")
            q.order_by = [self.parse_order_item()]
            while self.accept_op(","):
                q.order_by.append(self.parse_order_item())
        if self.accept_kw("LIMIT"):
            q.limit = self.expect_int()
            if self.accept_kw("OFFSET"):
                q.offset = self.expect_int()
        self.accept_op(";")
        if self.tok.kind != "eof":
            self.error("end of query")
        return q

    def parse_column(self):
        start = self.i
        expr = self.parse_expr()
        stop = self.i
        plain = stop - start == 1 and expr[0] == "name"
        alias = None
        if self.accept_kw("AS"):
            alias = self.expect_name()
        elif self.tok.kind == "name":
            alias = self.advance().value
        return expr, alias, self.text(start, stop), plain

    def parse_order_item(self):
        start = self.i
        expr = self.parse_expr()
        if self.i - start == 1 and self.tokens[start].kind == "int":
            item = ("pos", self.tokens[start].value)
        elif self.i - start == 1 and expr[0] == "name":
            item = ("ref", expr)
        else:
            item = ("expr", expr)
        descending = False
        if self.accept_kw("DESC"):
            descending = True
        else:
            self.accept_kw("ASC")
        return item, descending

    # -- expressions

    def parse_expr(self):
        left = self.parse_and()
        while self.accept_kw("OR"):
            left = ("or", left, self.parse_and())
        return left

    def parse_and(self):
        left = self.parse_not()
        while self.accept_kw("AND"):
            left = ("and", left, self.parse_not())
        return left

    def parse_not(self):
        if self.accept_kw("NOT"):
            return ("not", self.parse_not())
        return self.parse_comparison()

    def parse_comparison(self):
        left = self.parse_additive()
        while True:
            if self.at_op("=", "!=", "<>", "<", "<=", ">", ">="):
                op = self.advance().value
                if op == "<>":
                    op = "!="
                left = ("cmp", op, left, self.parse_additive())
            elif self.accept_kw("IS"):
                negated = bool(self.accept_kw("NOT"))
                self.expect_kw("NULL")
                left = ("isnull", left, negated)
            elif self.at_kw("NOT", "IN", "BETWEEN", "LIKE"):
                negated = bool(self.accept_kw("NOT"))
                if self.accept_kw("IN"):
                    self.expect_op("(")
                    items = [self.parse_expr()]
                    while self.accept_op(","):
                        items.append(self.parse_expr())
                    self.expect_op(")")
                    left = ("in", left, tuple(items), negated)
                elif self.accept_kw("BETWEEN"):
                    low = self.parse_additive()
                    self.expect_kw("AND")
                    high = self.parse_additive()
                    left = ("between", left, low, high, negated)
                elif self.accept_kw("LIKE"):
                    left = ("like", left, self.parse_additive(), negated)
                else:
                    self.error("IN, BETWEEN, or LIKE")
            else:
                return left

    def parse_additive(self):
        left = self.parse_multiplicative()
        while self.at_op("+", "-", "||"):
            op = self.advance().value
            left = ("bin", op, left, self.parse_multiplicative())
        return left

    def parse_multiplicative(self):
        left = self.parse_unary()
        while self.at_op("*", "/"):
            op = self.advance().value
            left = ("bin", op, left, self.parse_unary())
        return left

    def parse_unary(self):
        if self.accept_op("-"):
            return ("neg", self.parse_unary())
        return self.parse_primary()

    def parse_primary(self):
        tok = self.tok
        if tok.kind in ("int", "float", "str"):
            self.advance()
            return _lit(tok.value)
        if tok.kind == "kw" and tok.value in ("NULL", "TRUE", "FALSE"):
            self.advance()
            return _lit({"NULL": None, "TRUE": True, "FALSE": False}[tok.value])
        if tok.kind == "name":
            self.advance()
            if self.accept_op("("):
                return self.parse_call(tok.value)
            return ("name", tok.value)
        if self.accept_op("("):
            expr = self.parse_expr()
            self.expect_op(")")
            return expr
        self.error("an expression")

    def parse_call(self, name):
        name = name.upper()
        if name == "COUNT" and self.accept_op("*"):
            self.expect_op(")")
            return ("agg", name, None)
        args = []
        if not self.at_op(")"):
            args.append(self.parse_expr())
            while self.accept_op(","):
                args.append(self.parse_expr())
        self.expect_op(")")
        if name in AGGREGATES:
            if len(args) != 1:
                raise QueryError("%s takes exactly 1 argument" % name)
            return ("agg", name, args[0])
        if name not in SCALAR_ARITY:
            raise QueryError("unknown function %s" % name)
        low, high = SCALAR_ARITY[name]
        if len(args) < low or (high is not None and len(args) > high):
            if high is None:
                expected = "at least %d" % low
            elif low == high:
                expected = "exactly %d" % low
            else:
                expected = "%d to %d" % (low, high)
            raise QueryError("%s takes %s argument%s"
                             % (name, expected, "" if high == 1 else "s"))
        return ("func", name, tuple(args))


# ---------------------------------------------------------------------------
# Tables

_INT_RE = re.compile(r"-?[0-9]+")
_DECIMAL_RE = re.compile(r"-?[0-9]+\.[0-9]*|-?[0-9]*\.[0-9]+")


def _convert(field):
    if field == "":
        return None
    if _INT_RE.fullmatch(field):
        return int(field)
    if _DECIMAL_RE.fullmatch(field):
        return float(field)
    return field


def _load_table(directory, name):
    if not name or "/" in name or os.sep in name or name in (".", ".."):
        raise QueryError("invalid table name %r" % name)
    path = os.path.join(directory, name + ".csv")
    try:
        with open(path, newline="", encoding="utf-8-sig") as f:
            records = list(csv.reader(f))
    except FileNotFoundError:
        raise QueryError("unknown table %r" % name) from None
    except (OSError, UnicodeDecodeError, csv.Error) as e:
        raise QueryError("cannot read table %r: %s" % (name, e)) from None
    if not records:
        raise QueryError("table %r has no header" % name)
    header = records[0]
    width = len(header)
    rows = []
    for line_number, record in enumerate(records[1:], start=2):
        if not record:
            continue  # blank line
        if len(record) > width:
            raise QueryError("table %r: row %d has more fields than the header"
                             % (name, line_number))
        record = record + [""] * (width - len(record))
        rows.append([_convert(field) for field in record])
    return header, rows


# ---------------------------------------------------------------------------
# Name resolution and static checks


def _contains_aggregate(node):
    if node[0] == "agg":
        return True
    return any(_contains_aggregate(child) for child in _children(node))


def _children(node):
    tag = node[0]
    if tag in ("lit", "name", "col"):
        return ()
    if tag == "agg":
        return () if node[2] is None else (node[2],)
    if tag in ("neg", "not", "isnull"):
        return (node[1],)
    if tag in ("and", "or"):
        return (node[1], node[2])
    if tag in ("bin", "cmp"):
        return (node[2], node[3])
    if tag == "in":
        return (node[1],) + node[2]
    if tag == "between":
        return (node[1], node[2], node[3])
    if tag == "like":
        return (node[1], node[2])
    if tag == "func":
        return node[2]
    raise AssertionError(tag)


def _resolve(node, columns, in_aggregate=False):
    """Replace names with column indexes, checking aggregate nesting."""
    tag = node[0]
    if tag == "lit":
        return node
    if tag == "name":
        index = columns.get(node[1].lower())
        if index is None:
            raise QueryError("unknown column %r" % node[1])
        return ("col", index)
    if tag == "agg":
        if in_aggregate:
            raise QueryError("aggregate functions can't be nested")
        if node[2] is None:
            return node
        return ("agg", node[1], _resolve(node[2], columns, True))

    def r(child):
        return _resolve(child, columns, in_aggregate)

    if tag in ("neg", "not"):
        return (tag, r(node[1]))
    if tag in ("and", "or"):
        return (tag, r(node[1]), r(node[2]))
    if tag in ("bin", "cmp"):
        return (tag, node[1], r(node[2]), r(node[3]))
    if tag == "isnull":
        return (tag, r(node[1]), node[2])
    if tag == "in":
        return (tag, r(node[1]), tuple(r(item) for item in node[2]), node[3])
    if tag == "between":
        return (tag, r(node[1]), r(node[2]), r(node[3]), node[4])
    if tag == "like":
        return (tag, r(node[1]), r(node[2]), node[3])
    if tag == "func":
        return (tag, node[1], tuple(r(arg) for arg in node[2]))
    raise AssertionError(tag)


def _check_grouped(node, group_exprs, header):
    """Check that columns outside aggregates are GROUP BY expressions."""
    if node in group_exprs or node[0] == "agg":
        return
    if node[0] == "col":
        raise QueryError("column %r must appear in GROUP BY or be used in an "
                         "aggregate function" % header[node[1]])
    for child in _children(node):
        _check_grouped(child, group_exprs, header)


# ---------------------------------------------------------------------------
# Evaluation


def _kind(value):
    if isinstance(value, bool):
        return "boolean"
    if isinstance(value, (int, float)):
        return "number"
    return "string"


def _describe(value):
    return "%s %r" % (_kind(value), value)


def _compare(a, b):
    """Compare two non-NULL values, returning -1, 0, or 1."""
    if _kind(a) != _kind(b):
        raise QueryError("can't compare %s with %s"
                         % (_describe(a), _describe(b)))
    return (a > b) - (a < b)


def _sort_compare(a, b):
    """Like ``_compare`` but with NULL before everything."""
    if a is None or b is None:
        return (a is not None) - (b is not None)
    return _compare(a, b)


def _key(value):
    """A hashable key under which equal SQL values are equal."""
    if value is None:
        return ("null",)
    return (_kind(value), value)


def _check_bool(value, what):
    if value is not None and not isinstance(value, bool):
        raise QueryError("%s needs a boolean, got %s" % (what, _describe(value)))
    return value


def _check_number(value, what):
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        raise QueryError("%s needs a number, got %s" % (what, _describe(value)))
    return value


def _check_string(value, what):
    if not isinstance(value, str):
        raise QueryError("%s needs a string, got %s" % (what, _describe(value)))
    return value


def _text(value):
    if isinstance(value, bool):
        return "true" if value else "false"
    return str(value)


_CMP = {
    "=": lambda c: c == 0, "!=": lambda c: c != 0,
    "<": lambda c: c < 0, "<=": lambda c: c <= 0,
    ">": lambda c: c > 0, ">=": lambda c: c >= 0,
}


def _arith(op, a, b):
    if op == "||":
        return _text(a) + _text(b)
    _check_number(a, "'%s'" % op)
    _check_number(b, "'%s'" % op)
    try:
        if op == "+":
            return a + b
        if op == "-":
            return a - b
        if op == "*":
            return a * b
        if b == 0:
            return None
        return a / b
    except OverflowError:
        raise QueryError("numeric overflow in '%s'" % op) from None


@functools.lru_cache(maxsize=256)
def _like_regex(pattern):
    parts = []
    for ch in pattern:
        if ch == "%":
            parts.append(".*")
        elif ch == "_":
            parts.append(".")
        else:
            parts.append(re.escape(ch))
    return re.compile("".join(parts), re.DOTALL)


def _round(x, places):
    _check_number(x, "ROUND")
    if places is not None:
        if isinstance(places, bool) or not isinstance(places, int):
            raise QueryError("ROUND needs an integer number of places, got %s"
                             % _describe(places))
    if isinstance(x, float) and x != x or x in (float("inf"), float("-inf")):
        if places is None:
            raise QueryError("can't round %r to an integer" % x)
        return x
    with decimal.localcontext() as ctx:
        ctx.prec = 1000
        ctx.rounding = decimal.ROUND_HALF_UP  # halves away from zero
        d = decimal.Decimal(repr(x) if isinstance(x, float) else x)
        if places is None:
            return int(d.quantize(decimal.Decimal(1)))
        if places > 400:
            return float(x)
        if places < -400:
            return 0.0
        return float(d.quantize(decimal.Decimal(1).scaleb(-places)))


def _call(name, args):
    if name == "COALESCE":
        for value in args:
            if value is not None:
                return value
        return None
    if any(value is None for value in args):
        return None
    x = args[0]
    if name == "LOWER":
        return _check_string(x, name).lower()
    if name == "UPPER":
        return _check_string(x, name).upper()
    if name == "LENGTH":
        return len(_check_string(x, name))
    if name == "ABS":
        return abs(_check_number(x, name))
    if name == "ROUND":
        return _round(x, args[1] if len(args) > 1 else None)
    raise AssertionError(name)


def _aggregate(name, arg, rows):
    if arg is None:
        return len(rows)
    values = [v for v in (_eval(arg, row, None) for row in rows)
              if v is not None]
    if name == "COUNT":
        return len(values)
    if not values:
        return None
    if name in ("SUM", "AVG"):
        for v in values:
            _check_number(v, name)
        try:
            total = sum(values)
            return total / len(values) if name == "AVG" else total
        except OverflowError:
            raise QueryError("numeric overflow in %s" % name) from None
    best = values[0]
    for v in values[1:]:
        c = _compare(v, best)
        if (c < 0) if name == "MIN" else (c > 0):
            best = v
    return best


class _Group:
    def __init__(self, rows, values):
        self.rows = rows
        self.values = values  # GROUP BY expression -> its value


def _eval(node, row, group):
    """Evaluate ``node`` on ``row``, or on ``group`` in a grouped query."""
    if group is not None:
        if node in group.values:
            return group.values[node]
        if node[0] == "agg":
            return _aggregate(node[1], node[2], group.rows)
    tag = node[0]
    if tag == "lit":
        return node[2]
    if tag == "col":
        return row[node[1]]
    if tag == "and" or tag == "or":
        what = tag.upper()
        a = _check_bool(_eval(node[1], row, group), what)
        short = tag == "or"  # TRUE OR x is TRUE; FALSE AND x is FALSE
        if a is short:
            return a
        b = _check_bool(_eval(node[2], row, group), what)
        if b is short:
            return b
        if a is None or b is None:
            return None
        return not short
    if tag == "not":
        a = _check_bool(_eval(node[1], row, group), "NOT")
        return None if a is None else not a
    if tag == "isnull":
        a = _eval(node[1], row, group)
        return (a is not None) if node[2] else (a is None)
    if tag == "func" and node[1] == "COALESCE":
        for arg in node[2]:
            value = _eval(arg, row, group)
            if value is not None:
                return value
        return None
    if tag == "in":
        x = _eval(node[1], row, group)
        saw_null = x is None
        for item in node[2]:
            value = _eval(item, row, group)
            if value is None:
                saw_null = True
            elif x is not None and _compare(x, value) == 0:
                return not node[3]
        if saw_null:
            return None
        return node[3]

    if tag == "neg":
        a = _eval(node[1], row, group)
        return None if a is None else -_check_number(a, "unary '-'")
    if tag == "bin":
        a = _eval(node[2], row, group)
        b = _eval(node[3], row, group)
        if a is None or b is None:
            return None
        return _arith(node[1], a, b)
    if tag == "cmp":
        a = _eval(node[2], row, group)
        b = _eval(node[3], row, group)
        if a is None or b is None:
            return None
        return _CMP[node[1]](_compare(a, b))
    if tag == "between":
        x = _eval(node[1], row, group)
        low = _eval(node[2], row, group)
        high = _eval(node[3], row, group)
        if x is None:
            return None
        lower_ok = None if low is None else _compare(low, x) <= 0
        upper_ok = None if high is None else _compare(x, high) <= 0
        if lower_ok is False or upper_ok is False:
            result = False
        elif lower_ok is None or upper_ok is None:
            return None
        else:
            result = True
        return result != node[4]
    if tag == "like":
        x = _eval(node[1], row, group)
        pattern = _eval(node[2], row, group)
        if x is None or pattern is None:
            return None
        _check_string(x, "LIKE")
        _check_string(pattern, "LIKE")
        return bool(_like_regex(pattern).fullmatch(x)) != node[3]
    if tag == "func":
        return _call(node[1], [_eval(arg, row, group) for arg in node[2]])
    if tag == "agg":
        raise AssertionError("aggregate outside a grouped query")
    raise AssertionError(tag)


def _condition(node, row, group, clause):
    return _check_bool(_eval(node, row, group), clause) is True


# ---------------------------------------------------------------------------
# Execution


def _execute(q, directory):
    header, rows = _load_table(directory, q.table)
    names = {}
    for index, name in enumerate(header):
        names.setdefault(name.lower(), index)

    def resolve(node, clause=None):
        node = _resolve(node, names)
        if clause and _contains_aggregate(node):
            raise QueryError("aggregate functions can't be used in %s" % clause)
        return node

    # Output columns: (expression, name).
    if q.columns is None:
        columns = [(("col", i), name) for i, name in enumerate(header)]
    else:
        columns = []
        for expr, alias, text, plain in q.columns:
            node = resolve(expr)
            if alias is not None:
                name = alias
            elif plain:
                name = header[node[1]]
            else:
                name = text
            columns.append((node, name))
    output_names = [name.lower() for _, name in columns]

    where = resolve(q.where, "WHERE") if q.where is not None else None
    group_by = [resolve(expr, "GROUP BY") for expr in q.group_by]
    having = resolve(q.having) if q.having is not None else None

    # ORDER BY items: ("out", column index) or ("expr", expression).
    order_by = []
    for (kind, value), descending in q.order_by:
        if kind == "pos":
            if not 1 <= value <= len(columns):
                raise QueryError("ORDER BY position %d is not in the select "
                                 "list" % value)
            order_by.append((("out", value - 1), descending))
        elif kind == "ref" and value[1].lower() in output_names:
            index = output_names.index(value[1].lower())
            order_by.append((("out", index), descending))
        else:
            order_by.append((("expr", resolve(value)), descending))

    order_exprs = [v for (k, v), _ in order_by if k == "expr"]
    grouped = bool(group_by) or any(
        _contains_aggregate(node)
        for node in [c for c, _ in columns] + [having] + order_exprs
        if node is not None)

    if grouped:
        group_set = set(group_by)
        for node in [c for c, _ in columns] + [having] + order_exprs:
            if node is not None:
                _check_grouped(node, group_set, header)

    if where is not None:
        rows = [row for row in rows if _condition(where, row, None, "WHERE")]

    # Each unit is (row, group): a row of an ungrouped query or a group.
    if grouped:
        if group_by:
            groups = {}
            for row in rows:
                values = [_eval(expr, row, None) for expr in group_by]
                key = tuple(_key(v) for v in values)
                if key not in groups:
                    groups[key] = _Group([], dict(zip(group_by, values)))
                groups[key].rows.append(row)
            units = [(g.rows[0], g) for g in groups.values()]
        else:
            units = [(None, _Group(rows, {}))]
    else:
        units = [(row, None) for row in rows]

    if having is not None:
        units = [(row, group) for row, group in units
                 if _condition(having, row, group, "HAVING")]

    results = []
    for row, group in units:
        out = tuple(_eval(node, row, group) for node, _ in columns)
        keys = [out[v] if k == "out" else _eval(v, row, group)
                for (k, v), _ in order_by]
        results.append((out, keys))

    if q.distinct:
        seen = set()
        unique = []
        for out, keys in results:
            key = tuple(_key(v) for v in out)
            if key not in seen:
                seen.add(key)
                unique.append((out, keys))
        results = unique

    if order_by:
        directions = [descending for _, descending in order_by]

        def compare(a, b):
            for x, y, descending in zip(a[1], b[1], directions):
                c = _sort_compare(x, y)
                if c:
                    return -c if descending else c
            return 0

        results.sort(key=functools.cmp_to_key(compare))

    end = None if q.limit is None else q.offset + q.limit
    results = results[q.offset:end]
    return Result([name for _, name in columns], [out for out, _ in results])

"""Run SQL SELECT queries against CSV files. See SPEC.md."""

import csv
import decimal
import functools
import os
import re

__all__ = ["QueryError", "Result", "run"]


class QueryError(Exception):
    """Raised for any problem with a query."""


class Result:
    """The result of a query: ``columns`` (names) and ``rows`` (tuples)."""

    def __init__(self, columns, rows):
        self.columns = columns
        self.rows = rows

    def __repr__(self):
        return "Result(columns=%r, rows=%r)" % (self.columns, self.rows)

    def __eq__(self, other):
        if not isinstance(other, Result):
            return NotImplemented
        return self.columns == other.columns and self.rows == other.rows


def run(sql, directory="."):
    """Run ``sql`` against the CSV files in ``directory``."""
    if not isinstance(sql, str):
        raise QueryError("query must be a string")
    query = _Parser(_tokenize(sql), sql).parse_query()
    return _execute(query, directory)


# ---------------------------------------------------------------------------
# Lexer

KEYWORDS = {
    "SELECT", "DISTINCT", "FROM", "WHERE", "GROUP", "BY", "HAVING", "ORDER",
    "ASC", "DESC", "LIMIT", "OFFSET", "AS", "AND", "OR", "NOT", "IS", "NULL",
    "IN", "BETWEEN", "LIKE", "TRUE", "FALSE",
}

_NUMBER_RE = re.compile(r"[0-9]+\.[0-9]*|\.[0-9]+|[0-9]+")
_NAME_RE = re.compile(r"[^\W\d]\w*")
_OPERATORS = ("<=", ">=", "<>", "!=", "||", "=", "<", ">", "+", "-", "*",
              "/", "(", ")", ",", ";")


class _Token:
    __slots__ = ("kind", "value", "start", "end")

    def __init__(self, kind, value, start, end):
        # kind is one of: kw, name, int, float, str, op, eof
        self.kind = kind
        self.value = value
        self.start = start
        self.end = end

    def describe(self):
        if self.kind == "eof":
            return "end of query"
        if self.kind == "str":
            return "string literal"
        return repr(str(self.value))


def _read_quoted(sql, pos, quote):
    """Read a quoted string starting at ``pos``; return (text, end)."""
    parts = []
    i = pos + 1
    while True:
        j = sql.find(quote, i)
        if j < 0:
            what = "string" if quote == "'" else "quoted name"
            raise QueryError("unterminated %s at position %d" % (what, pos))
        parts.append(sql[i:j])
        if sql.startswith(quote, j + 1):
            parts.append(quote)
            i = j + 2
        else:
            return "".join(parts), j + 1


def _tokenize(sql):
    tokens = []
    pos = 0
    n = len(sql)
    while pos < n:
        ch = sql[pos]
        if ch.isspace():
            pos += 1
            continue
        if ch == "'":
            text, end = _read_quoted(sql, pos, "'")
            tokens.append(_Token("str", text, pos, end))
            pos = end
            continue
        if ch == '"':
            text, end = _read_quoted(sql, pos, '"')
            tokens.append(_Token("name", text, pos, end))
            pos = end
            continue
        m = _NUMBER_RE.match(sql, pos)
        if m:
            end = m.end()
            if end < n and (sql[end].isalnum() or sql[end] in "_."):
                raise QueryError("invalid number at position %d" % pos)
            text = m.group()
            if "." in text:
                tokens.append(_Token("float", float(text), pos, end))
            else:
                tokens.append(_Token("int", int(text), pos, end))
            pos = end
            continue
        m = _NAME_RE.match(sql, pos)
        if m:
            word = m.group()
            if word.upper() in KEYWORDS:
                tokens.append(_Token("kw", word.upper(), pos, m.end()))
            else:
                tokens.append(_Token("name", word, pos, m.end()))
            pos = m.end()
            continue
        for op in _OPERATORS:
            if sql.startswith(op, pos):
                tokens.append(_Token("op", op, pos, pos + len(op)))
                pos += len(op)
                break
        else:
            raise QueryError("unexpected character %r at position %d"
                             % (ch, pos))
    tokens.append(_Token("eof", None, n, n))
    return tokens


# ---------------------------------------------------------------------------
# Parser
#
# Expressions are nested tuples, so they can be compared and hashed (GROUP BY
# matching relies on this):
#
#   ("lit", type_name, value)        ("name", text)  -> ("col", index)
#   ("neg", e)   ("not", e)          ("and", a, b)   ("or", a, b)
#   ("bin", op, a, b)                ("cmp", op, a, b)
#   ("isnull", e, negated)           ("in", e, items, negated)
#   ("between", e, lo, hi, negated)  ("like", e, pattern, negated)
#   ("func", NAME, args)             ("agg", NAME, arg_or_None)

SCALAR_ARITY = {
    "LOWER": (1, 1), "UPPER": (1, 1), "LENGTH": (1, 1), "ABS": (1, 1),
    "ROUND": (1, 2), "COALESCE": (1, None),
}
AGGREGATES = {"COUNT", "SUM", "AVG", "MIN", "MAX"}


def _lit(value):
    return ("lit", type(value).__name__, value)


class _Query:
    def __init__(self):
        self.distinct = False
        self.columns = None   # None for "*", else [(expr, alias, text, plain)]
        self.table = None
        self.where = None
        self.group_by = []
        self.having = None
        self.order_by = []    # [(item, descending)]
        self.limit = None
        self.offset = 0


class _Parser:
    def __init__(self, tokens, sql):
        self.tokens = tokens
        self.sql = sql
        self.i = 0

    # -- helpers

    @property
    def tok(self):
        return self.tokens[self.i]

    def advance(self):
        tok = self.tokens[self.i]
        self.i += 1
        return tok

    def at_kw(self, *words):
        return self.tok.kind == "kw" and self.tok.value in words

    def at_op(self, *ops):
        return self.tok.kind == "op" and self.tok.value in ops

    def accept_kw(self, word):
        if self.at_kw(word):
            return self.advance()
        return None

    def accept_op(self, op):
        if self.at_op(op):
            return self.advance()
        return None

    def error(self, expected):
        tok = self.tok
        raise QueryError("syntax error at position %d: expected %s, found %s"
                         % (tok.start, expected, tok.describe()))

    def expect_kw(self, word):
        if not self.at_kw(word):
            self.error(word)
        return self.advance()

    def expect_op(self, op):
        if not self.at_op(op):
            self.error(repr(op))
        return self.advance()

    def expect_name(self):
        if self.tok.kind != "name":
            self.error("a name")
        return self.advance().value

    def expect_int(self):
        if self.tok.kind != "int":
            self.error("an integer")
        return self.advance().value

    def text(self, start, stop):
        """Source text of tokens ``start`` up to (excluding) ``stop``."""
        return self.sql[self.tokens[start].start:self.tokens[stop - 1].end]

    # -- query

    def parse_query(self):
        q = _Query()
        self.expect_kw("SELECT")
        q.distinct = bool(self.accept_kw("DISTINCT"))
        if self.accept_op("*"):
            q.columns = None
        else:
            q.columns = [self.parse_column()]
            while self.accept_op(","):
                q.columns.append(self.parse_column())
        self.expect_kw("FROM")
        q.table = self.expect_name()
        if self.accept_kw("WHERE"):
            q.where = self.parse_expr()
        if self.accept_kw("GROUP"):
            self.expect_kw("BY")
            q.group_by = [self.parse_expr()]
            while self.accept_op(","):
                q.group_by.append(self.parse_expr())
        if self.accept_kw("HAVING"):
            q.having = self.parse_expr()
        if self.accept_kw("ORDER"):
            self.expect_kw("BY")
            q.order_by = [self.parse_order_item()]
            while self.accept_op(","):
                q.order_by.append(self.parse_order_item())
        if self.accept_kw("LIMIT"):
            q.limit = self.expect_int()
            if self.accept_kw("OFFSET"):
                q.offset = self.expect_int()
        self.accept_op(";")
        if self.tok.kind != "eof":
            self.error("end of query")
        return q

    def parse_column(self):
        start = self.i
        expr = self.parse_expr()
        stop = self.i
        plain = stop - start == 1 and expr[0] == "name"
        alias = None
        if self.accept_kw("AS"):
            alias = self.expect_name()
        elif self.tok.kind == "name":
            alias = self.advance().value
        return expr, alias, self.text(start, stop), plain

    def parse_order_item(self):
        start = self.i
        expr = self.parse_expr()
        if self.i - start == 1 and self.tokens[start].kind == "int":
            item = ("pos", self.tokens[start].value)
        elif self.i - start == 1 and expr[0] == "name":
            item = ("ref", expr)
        else:
            item = ("expr", expr)
        descending = False
        if self.accept_kw("DESC"):
            descending = True
        else:
            self.accept_kw("ASC")
        return item, descending

    # -- expressions

    def parse_expr(self):
        left = self.parse_and()
        while self.accept_kw("OR"):
            left = ("or", left, self.parse_and())
        return left

    def parse_and(self):
        left = self.parse_not()
        while self.accept_kw("AND"):
            left = ("and", left, self.parse_not())
        return left

    def parse_not(self):
        if self.accept_kw("NOT"):
            return ("not", self.parse_not())
        return self.parse_comparison()

    def parse_comparison(self):
        left = self.parse_additive()
        while True:
            if self.at_op("=", "!=", "<>", "<", "<=", ">", ">="):
                op = self.advance().value
                if op == "<>":
                    op = "!="
                left = ("cmp", op, left, self.parse_additive())
            elif self.accept_kw("IS"):
                negated = bool(self.accept_kw("NOT"))
                self.expect_kw("NULL")
                left = ("isnull", left, negated)
            elif self.at_kw("NOT", "IN", "BETWEEN", "LIKE"):
                negated = bool(self.accept_kw("NOT"))
                if self.accept_kw("IN"):
                    self.expect_op("(")
                    items = [self.parse_expr()]
                    while self.accept_op(","):
                        items.append(self.parse_expr())
                    self.expect_op(")")
                    left = ("in", left, tuple(items), negated)
                elif self.accept_kw("BETWEEN"):
                    low = self.parse_additive()
                    self.expect_kw("AND")
                    high = self.parse_additive()
                    left = ("between", left, low, high, negated)
                elif self.accept_kw("LIKE"):
                    left = ("like", left, self.parse_additive(), negated)
                else:
                    self.error("IN, BETWEEN, or LIKE")
            else:
                return left

    def parse_additive(self):
        left = self.parse_multiplicative()
        while self.at_op("+", "-", "||"):
            op = self.advance().value
            left = ("bin", op, left, self.parse_multiplicative())
        return left

    def parse_multiplicative(self):
        left = self.parse_unary()
        while self.at_op("*", "/"):
            op = self.advance().value
            left = ("bin", op, left, self.parse_unary())
        return left

    def parse_unary(self):
        if self.accept_op("-"):
            return ("neg", self.parse_unary())
        return self.parse_primary()

    def parse_primary(self):
        tok = self.tok
        if tok.kind in ("int", "float", "str"):
            self.advance()
            return _lit(tok.value)
        if tok.kind == "kw" and tok.value in ("NULL", "TRUE", "FALSE"):
            self.advance()
            return _lit({"NULL": None, "TRUE": True, "FALSE": False}[tok.value])
        if tok.kind == "name":
            self.advance()
            if self.accept_op("("):
                return self.parse_call(tok.value)
            return ("name", tok.value)
        if self.accept_op("("):
            expr = self.parse_expr()
            self.expect_op(")")
            return expr
        self.error("an expression")

    def parse_call(self, name):
        name = name.upper()
        if name == "COUNT" and self.accept_op("*"):
            self.expect_op(")")
            return ("agg", name, None)
        args = []
        if not self.at_op(")"):
            args.append(self.parse_expr())
            while self.accept_op(","):
                args.append(self.parse_expr())
        self.expect_op(")")
        if name in AGGREGATES:
            if len(args) != 1:
                raise QueryError("%s takes exactly 1 argument" % name)
            return ("agg", name, args[0])
        if name not in SCALAR_ARITY:
            raise QueryError("unknown function %s" % name)
        low, high = SCALAR_ARITY[name]
        if len(args) < low or (high is not None and len(args) > high):
            if high is None:
                expected = "at least %d" % low
            elif low == high:
                expected = "exactly %d" % low
            else:
                expected = "%d to %d" % (low, high)
            raise QueryError("%s takes %s argument%s"
                             % (name, expected, "" if high == 1 else "s"))
        return ("func", name, tuple(args))


# ---------------------------------------------------------------------------
# Tables

_INT_RE = re.compile(r"-?[0-9]+")
_DECIMAL_RE = re.compile(r"-?[0-9]+\.[0-9]*|-?[0-9]*\.[0-9]+")


def _convert(field):
    if field == "":
        return None
    if _INT_RE.fullmatch(field):
        return int(field)
    if _DECIMAL_RE.fullmatch(field):
        return float(field)
    return field


def _load_table(directory, name):
    if not name or "/" in name or os.sep in name or name in (".", ".."):
        raise QueryError("invalid table name %r" % name)
    path = os.path.join(directory, name + ".csv")
    try:
        with open(path, newline="", encoding="utf-8-sig") as f:
            records = list(csv.reader(f))
    except FileNotFoundError:
        raise QueryError("unknown table %r" % name) from None
    except (OSError, UnicodeDecodeError, csv.Error) as e:
        raise QueryError("cannot read table %r: %s" % (name, e)) from None
    if not records:
        raise QueryError("table %r has no header" % name)
    header = records[0]
    width = len(header)
    rows = []
    for line_number, record in enumerate(records[1:], start=2):
        if not record:
            continue  # blank line
        if len(record) > width:
            raise QueryError("table %r: row %d has more fields than the header"
                             % (name, line_number))
        record = record + [""] * (width - len(record))
        rows.append([_convert(field) for field in record])
    return header, rows


# ---------------------------------------------------------------------------
# Name resolution and static checks


def _contains_aggregate(node):
    if node[0] == "agg":
        return True
    return any(_contains_aggregate(child) for child in _children(node))


def _children(node):
    tag = node[0]
    if tag in ("lit", "name", "col"):
        return ()
    if tag == "agg":
        return () if node[2] is None else (node[2],)
    if tag in ("neg", "not", "isnull"):
        return (node[1],)
    if tag in ("and", "or"):
        return (node[1], node[2])
    if tag in ("bin", "cmp"):
        return (node[2], node[3])
    if tag == "in":
        return (node[1],) + node[2]
    if tag == "between":
        return (node[1], node[2], node[3])
    if tag == "like":
        return (node[1], node[2])
    if tag == "func":
        return node[2]
    raise AssertionError(tag)


def _resolve(node, columns, in_aggregate=False):
    """Replace names with column indexes, checking aggregate nesting."""
    tag = node[0]
    if tag == "lit":
        return node
    if tag == "name":
        index = columns.get(node[1].lower())
        if index is None:
            raise QueryError("unknown column %r" % node[1])
        return ("col", index)
    if tag == "agg":
        if in_aggregate:
            raise QueryError("aggregate functions can't be nested")
        if node[2] is None:
            return node
        return ("agg", node[1], _resolve(node[2], columns, True))

    def r(child):
        return _resolve(child, columns, in_aggregate)

    if tag in ("neg", "not"):
        return (tag, r(node[1]))
    if tag in ("and", "or"):
        return (tag, r(node[1]), r(node[2]))
    if tag in ("bin", "cmp"):
        return (tag, node[1], r(node[2]), r(node[3]))
    if tag == "isnull":
        return (tag, r(node[1]), node[2])
    if tag == "in":
        return (tag, r(node[1]), tuple(r(item) for item in node[2]), node[3])
    if tag == "between":
        return (tag, r(node[1]), r(node[2]), r(node[3]), node[4])
    if tag == "like":
        return (tag, r(node[1]), r(node[2]), node[3])
    if tag == "func":
        return (tag, node[1], tuple(r(arg) for arg in node[2]))
    raise AssertionError(tag)


def _check_grouped(node, group_exprs, header):
    """Check that columns outside aggregates are GROUP BY expressions."""
    if node in group_exprs or node[0] == "agg":
        return
    if node[0] == "col":
        raise QueryError("column %r must appear in GROUP BY or be used in an "
                         "aggregate function" % header[node[1]])
    for child in _children(node):
        _check_grouped(child, group_exprs, header)


# ---------------------------------------------------------------------------
# Evaluation


def _kind(value):
    if isinstance(value, bool):
        return "boolean"
    if isinstance(value, (int, float)):
        return "number"
    return "string"


def _describe(value):
    return "%s %r" % (_kind(value), value)


def _compare(a, b):
    """Compare two non-NULL values, returning -1, 0, or 1."""
    if _kind(a) != _kind(b):
        raise QueryError("can't compare %s with %s"
                         % (_describe(a), _describe(b)))
    return (a > b) - (a < b)


def _sort_compare(a, b):
    """Like ``_compare`` but with NULL before everything."""
    if a is None or b is None:
        return (a is not None) - (b is not None)
    return _compare(a, b)


def _key(value):
    """A hashable key under which equal SQL values are equal."""
    if value is None:
        return ("null",)
    return (_kind(value), value)


def _check_bool(value, what):
    if value is not None and not isinstance(value, bool):
        raise QueryError("%s needs a boolean, got %s" % (what, _describe(value)))
    return value


def _check_number(value, what):
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        raise QueryError("%s needs a number, got %s" % (what, _describe(value)))
    return value


def _check_string(value, what):
    if not isinstance(value, str):
        raise QueryError("%s needs a string, got %s" % (what, _describe(value)))
    return value


def _text(value):
    if isinstance(value, bool):
        return "true" if value else "false"
    return str(value)


_CMP = {
    "=": lambda c: c == 0, "!=": lambda c: c != 0,
    "<": lambda c: c < 0, "<=": lambda c: c <= 0,
    ">": lambda c: c > 0, ">=": lambda c: c >= 0,
}


def _arith(op, a, b):
    if op == "||":
        return _text(a) + _text(b)
    _check_number(a, "'%s'" % op)
    _check_number(b, "'%s'" % op)
    try:
        if op == "+":
            return a + b
        if op == "-":
            return a - b
        if op == "*":
            return a * b
        if b == 0:
            return None
        return a / b
    except OverflowError:
        raise QueryError("numeric overflow in '%s'" % op) from None


@functools.lru_cache(maxsize=256)
def _like_regex(pattern):
    parts = []
    for ch in pattern:
        if ch == "%":
            parts.append(".*")
        elif ch == "_":
            parts.append(".")
        else:
            parts.append(re.escape(ch))
    return re.compile("".join(parts), re.DOTALL)


def _round(x, places):
    _check_number(x, "ROUND")
    if places is not None:
        if isinstance(places, bool) or not isinstance(places, int):
            raise QueryError("ROUND needs an integer number of places, got %s"
                             % _describe(places))
    if isinstance(x, float) and x != x or x in (float("inf"), float("-inf")):
        if places is None:
            raise QueryError("can't round %r to an integer" % x)
        return x
    with decimal.localcontext() as ctx:
        ctx.prec = 1000
        ctx.rounding = decimal.ROUND_HALF_UP  # halves away from zero
        d = decimal.Decimal(repr(x) if isinstance(x, float) else x)
        if places is None:
            return int(d.quantize(decimal.Decimal(1)))
        if places > 400:
            return float(x)
        if places < -400:
            return 0.0
        return float(d.quantize(decimal.Decimal(1).scaleb(-places)))


def _call(name, args):
    if any(value is None for value in args):
        return None
    x = args[0]
    if name == "LOWER":
        return _check_string(x, name).lower()
    if name == "UPPER":
        return _check_string(x, name).upper()
    if name == "LENGTH":
        return len(_check_string(x, name))
    if name == "ABS":
        return abs(_check_number(x, name))
    if name == "ROUND":
        return _round(x, args[1] if len(args) > 1 else None)
    raise AssertionError(name)


def _aggregate(name, arg, rows):
    if arg is None:
        return len(rows)
    values = [v for v in (_eval(arg, row, None) for row in rows)
              if v is not None]
    if name == "COUNT":
        return len(values)
    if not values:
        return None
    if name in ("SUM", "AVG"):
        for v in values:
            _check_number(v, name)
        try:
            total = sum(values)
            return total / len(values) if name == "AVG" else total
        except OverflowError:
            raise QueryError("numeric overflow in %s" % name) from None
    best = values[0]
    for v in values[1:]:
        c = _compare(v, best)
        if (c < 0) if name == "MIN" else (c > 0):
            best = v
    return best


class _Group:
    def __init__(self, rows, values):
        self.rows = rows
        self.values = values  # GROUP BY expression -> its value


def _eval(node, row, group):
    """Evaluate ``node`` on ``row``, or on ``group`` in a grouped query."""
    if group is not None:
        if node in group.values:
            return group.values[node]
        if node[0] == "agg":
            return _aggregate(node[1], node[2], group.rows)
    tag = node[0]
    if tag == "lit":
        return node[2]
    if tag == "col":
        return row[node[1]]
    if tag == "and" or tag == "or":
        what = tag.upper()
        a = _check_bool(_eval(node[1], row, group), what)
        short = tag == "or"  # TRUE OR x is TRUE; FALSE AND x is FALSE
        if a is short:
            return a
        b = _check_bool(_eval(node[2], row, group), what)
        if b is short:
            return b
        if a is None or b is None:
            return None
        return not short
    if tag == "not":
        a = _check_bool(_eval(node[1], row, group), "NOT")
        return None if a is None else not a
    if tag == "isnull":
        a = _eval(node[1], row, group)
        return (a is not None) if node[2] else (a is None)
    if tag == "func" and node[1] == "COALESCE":
        for arg in node[2]:
            value = _eval(arg, row, group)
            if value is not None:
                return value
        return None
    if tag == "in":
        x = _eval(node[1], row, group)
        saw_null = x is None
        for item in node[2]:
            value = _eval(item, row, group)
            if value is None:
                saw_null = True
            elif x is not None and _compare(x, value) == 0:
                return not node[3]
        if saw_null:
            return None
        return node[3]

    if tag == "neg":
        a = _eval(node[1], row, group)
        return None if a is None else -_check_number(a, "unary '-'")
    if tag == "bin":
        a = _eval(node[2], row, group)
        b = _eval(node[3], row, group)
        if a is None or b is None:
            return None
        return _arith(node[1], a, b)
    if tag == "cmp":
        a = _eval(node[2], row, group)
        b = _eval(node[3], row, group)
        if a is None or b is None:
            return None
        return _CMP[node[1]](_compare(a, b))
    if tag == "between":
        x = _eval(node[1], row, group)
        low = _eval(node[2], row, group)
        high = _eval(node[3], row, group)
        if x is None:
            return None
        lower_ok = None if low is None else _compare(low, x) <= 0
        upper_ok = None if high is None else _compare(x, high) <= 0
        if lower_ok is False or upper_ok is False:
            result = False
        elif lower_ok is None or upper_ok is None:
            return None
        else:
            result = True
        return result != node[4]
    if tag == "like":
        x = _eval(node[1], row, group)
        pattern = _eval(node[2], row, group)
        if x is None or pattern is None:
            return None
        _check_string(x, "LIKE")
        _check_string(pattern, "LIKE")
        return bool(_like_regex(pattern).fullmatch(x)) != node[3]
    if tag == "func":
        return _call(node[1], [_eval(arg, row, group) for arg in node[2]])
    if tag == "agg":
        raise AssertionError("aggregate outside a grouped query")
    raise AssertionError(tag)


def _condition(node, row, group, clause):
    return _check_bool(_eval(node, row, group), clause) is True


# ---------------------------------------------------------------------------
# Execution


def _execute(q, directory):
    header, rows = _load_table(directory, q.table)
    names = {}
    for index, name in enumerate(header):
        names.setdefault(name.lower(), index)

    def resolve(node, clause=None):
        node = _resolve(node, names)
        if clause and _contains_aggregate(node):
            raise QueryError("aggregate functions can't be used in %s" % clause)
        return node

    # Output columns: (expression, name).
    if q.columns is None:
        columns = [(("col", i), name) for i, name in enumerate(header)]
    else:
        columns = []
        for expr, alias, text, plain in q.columns:
            node = resolve(expr)
            if alias is not None:
                name = alias
            elif plain:
                name = header[node[1]]
            else:
                name = text
            columns.append((node, name))
    output_names = [name.lower() for _, name in columns]

    where = resolve(q.where, "WHERE") if q.where is not None else None
    group_by = [resolve(expr, "GROUP BY") for expr in q.group_by]
    having = resolve(q.having) if q.having is not None else None

    # ORDER BY items: ("out", column index) or ("expr", expression).
    order_by = []
    for (kind, value), descending in q.order_by:
        if kind == "pos":
            if not 1 <= value <= len(columns):
                raise QueryError("ORDER BY position %d is not in the select "
                                 "list" % value)
            order_by.append((("out", value - 1), descending))
        elif kind == "ref" and value[1].lower() in output_names:
            index = output_names.index(value[1].lower())
            order_by.append((("out", index), descending))
        else:
            order_by.append((("expr", resolve(value)), descending))

    order_exprs = [v for (k, v), _ in order_by if k == "expr"]
    grouped = bool(group_by) or any(
        _contains_aggregate(node)
        for node in [c for c, _ in columns] + [having] + order_exprs
        if node is not None)

    if grouped:
        group_set = set(group_by)
        for node in [c for c, _ in columns] + [having] + order_exprs:
            if node is not None:
                _check_grouped(node, group_set, header)

    if where is not None:
        rows = [row for row in rows if _condition(where, row, None, "WHERE")]

    # Each unit is (row, group): a row of an ungrouped query or a group.
    if grouped:
        if group_by:
            groups = {}
            for row in rows:
                values = [_eval(expr, row, None) for expr in group_by]
                key = tuple(_key(v) for v in values)
                if key not in groups:
                    groups[key] = _Group([], dict(zip(group_by, values)))
                groups[key].rows.append(row)
            units = [(g.rows[0], g) for g in groups.values()]
        else:
            units = [(None, _Group(rows, {}))]
    else:
        units = [(row, None) for row in rows]

    if having is not None:
        units = [(row, group) for row, group in units
                 if _condition(having, row, group, "HAVING")]

    results = []
    for row, group in units:
        out = tuple(_eval(node, row, group) for node, _ in columns)
        keys = [out[v] if k == "out" else _eval(v, row, group)
                for (k, v), _ in order_by]
        results.append((out, keys))

    if q.distinct:
        seen = set()
        unique = []
        for out, keys in results:
            key = tuple(_key(v) for v in out)
            if key not in seen:
                seen.add(key)
                unique.append((out, keys))
        results = unique

    if order_by:
        directions = [descending for _, descending in order_by]

        def compare(a, b):
            for x, y, descending in zip(a[1], b[1], directions):
                c = _sort_compare(x, y)
                if c:
                    return -c if descending else c
            return 0

        results.sort(key=functools.cmp_to_key(compare))

    end = None if q.limit is None else q.offset + q.limit
    results = results[q.offset:end]
    return Result([name for _, name in columns], [out for out, _ in results])

"""Run SQL SELECT queries against CSV files. See SPEC.md."""

import csv
import decimal
import functools
import os
import re

__all__ = ["QueryError", "Result", "run"]


class QueryError(Exception):
    """Raised for any problem with a query."""


class Result:
    """The result of a query: ``columns`` (names) and ``rows`` (tuples)."""

    def __init__(self, columns, rows):
        self.columns = columns
        self.rows = rows

    def __repr__(self):
        return "Result(columns=%r, rows=%r)" % (self.columns, self.rows)

    def __eq__(self, other):
        if not isinstance(other, Result):
            return NotImplemented
        return self.columns == other.columns and self.rows == other.rows


def run(sql, directory="."):
    """Run ``sql`` against the CSV files in ``directory``."""
    if not isinstance(sql, str):
        raise QueryError("query must be a string")
    query = _Parser(_tokenize(sql), sql).parse_query()
    return _execute(query, directory)


# ---------------------------------------------------------------------------
# Lexer

KEYWORDS = {
    "SELECT", "DISTINCT", "FROM", "WHERE", "GROUP", "BY", "HAVING", "ORDER",
    "ASC", "DESC", "LIMIT", "OFFSET", "AS", "AND", "OR", "NOT", "IS", "NULL",
    "IN", "BETWEEN", "LIKE", "TRUE", "FALSE",
}

_NUMBER_RE = re.compile(r"[0-9]+\.[0-9]*|\.[0-9]+|[0-9]+")
_NAME_RE = re.compile(r"[^\W\d]\w*")
_OPERATORS = ("<=", ">=", "<>", "!=", "||", "=", "<", ">", "+", "-", "*",
              "/", "(", ")", ",", ";")


class _Token:
    __slots__ = ("kind", "value", "start", "end")

    def __init__(self, kind, value, start, end):
        # kind is one of: kw, name, int, float, str, op, eof
        self.kind = kind
        self.value = value
        self.start = start
        self.end = end

    def describe(self):
        if self.kind == "eof":
            return "end of query"
        if self.kind == "str":
            return "string literal"
        return repr(str(self.value))


def _read_quoted(sql, pos, quote):
    """Read a quoted string starting at ``pos``; return (text, end)."""
    parts = []
    i = pos + 1
    while True:
        j = sql.find(quote, i)
        if j < 0:
            what = "string" if quote == "'" else "quoted name"
            raise QueryError("unterminated %s at position %d" % (what, pos))
        parts.append(sql[i:j])
        if sql.startswith(quote, j + 1):
            parts.append(quote)
            i = j + 2
        else:
            return "".join(parts), j + 1


def _tokenize(sql):
    tokens = []
    pos = 0
    n = len(sql)
    while pos < n:
        ch = sql[pos]
        if ch.isspace():
            pos += 1
            continue
        if ch == "'":
            text, end = _read_quoted(sql, pos, "'")
            tokens.append(_Token("str", text, pos, end))
            pos = end
            continue
        if ch == '"':
            text, end = _read_quoted(sql, pos, '"')
            tokens.append(_Token("name", text, pos, end))
            pos = end
            continue
        m = _NUMBER_RE.match(sql, pos)
        if m:
            end = m.end()
            if end < n and (sql[end].isalnum() or sql[end] in "_."):
                raise QueryError("invalid number at position %d" % pos)
            text = m.group()
            if "." in text:
                tokens.append(_Token("float", float(text), pos, end))
            else:
                tokens.append(_Token("int", int(text), pos, end))
            pos = end
            continue
        m = _NAME_RE.match(sql, pos)
        if m:
            word = m.group()
            if word.upper() in KEYWORDS:
                tokens.append(_Token("kw", word.upper(), pos, m.end()))
            else:
                tokens.append(_Token("name", word, pos, m.end()))
            pos = m.end()
            continue
        for op in _OPERATORS:
            if sql.startswith(op, pos):
                tokens.append(_Token("op", op, pos, pos + len(op)))
                pos += len(op)
                break
        else:
            raise QueryError("unexpected character %r at position %d"
                             % (ch, pos))
    tokens.append(_Token("eof", None, n, n))
    return tokens


# ---------------------------------------------------------------------------
# Parser
#
# Expressions are nested tuples, so they can be compared and hashed (GROUP BY
# matching relies on this):
#
#   ("lit", type_name, value)        ("name", text)  -> ("col", index)
#   ("neg", e)   ("not", e)          ("and", a, b)   ("or", a, b)
#   ("bin", op, a, b)                ("cmp", op, a, b)
#   ("isnull", e, negated)           ("in", e, items, negated)
#   ("between", e, lo, hi, negated)  ("like", e, pattern, negated)
#   ("func", NAME, args)             ("agg", NAME, arg_or_None)

SCALAR_ARITY = {
    "LOWER": (1, 1), "UPPER": (1, 1), "LENGTH": (1, 1), "ABS": (1, 1),
    "ROUND": (1, 2), "COALESCE": (1, None),
}
AGGREGATES = {"COUNT", "SUM", "AVG", "MIN", "MAX"}


def _lit(value):
    return ("lit", type(value).__name__, value)


class _Query:
    def __init__(self):
        self.distinct = False
        self.columns = None   # None for "*", else [(expr, alias, text, plain)]
        self.table = None
        self.where = None
        self.group_by = []
        self.having = None
        self.order_by = []    # [(item, descending)]
        self.limit = None
        self.offset = 0


class _Parser:
    def __init__(self, tokens, sql):
        self.tokens = tokens
        self.sql = sql
        self.i = 0

    # -- helpers

    @property
    def tok(self):
        return self.tokens[self.i]

    def advance(self):
        tok = self.tokens[self.i]
        self.i += 1
        return tok

    def at_kw(self, *words):
        return self.tok.kind == "kw" and self.tok.value in words

    def at_op(self, *ops):
        return self.tok.kind == "op" and self.tok.value in ops

    def accept_kw(self, word):
        if self.at_kw(word):
            return self.advance()
        return None

    def accept_op(self, op):
        if self.at_op(op):
            return self.advance()
        return None

    def error(self, expected):
        tok = self.tok
        raise QueryError("syntax error at position %d: expected %s, found %s"
                         % (tok.start, expected, tok.describe()))

    def expect_kw(self, word):
        if not self.at_kw(word):
            self.error(word)
        return self.advance()

    def expect_op(self, op):
        if not self.at_op(op):
            self.error(repr(op))
        return self.advance()

    def expect_name(self):
        if self.tok.kind != "name":
            self.error("a name")
        return self.advance().value

    def expect_int(self):
        if self.tok.kind != "int":
            self.error("an integer")
        return self.advance().value

    def text(self, start, stop):
        """Source text of tokens ``start`` up to (excluding) ``stop``."""
        return self.sql[self.tokens[start].start:self.tokens[stop - 1].end]

    # -- query

    def parse_query(self):
        q = _Query()
        self.expect_kw("SELECT")
        q.distinct = bool(self.accept_kw("DISTINCT"))
        if self.accept_op("*"):
            q.columns = None
        else:
            q.columns = [self.parse_column()]
            while self.accept_op(","):
                q.columns.append(self.parse_column())
        self.expect_kw("FROM")
        q.table = self.expect_name()
        if self.accept_kw("WHERE"):
            q.where = self.parse_expr()
        if self.accept_kw("GROUP"):
            self.expect_kw("BY")
            q.group_by = [self.parse_expr()]
            while self.accept_op(","):
                q.group_by.append(self.parse_expr())
        if self.accept_kw("HAVING"):
            q.having = self.parse_expr()
        if self.accept_kw("ORDER"):
            self.expect_kw("BY")
            q.order_by = [self.parse_order_item()]
            while self.accept_op(","):
                q.order_by.append(self.parse_order_item())
        if self.accept_kw("LIMIT"):
            q.limit = self.expect_int()
            if self.accept_kw("OFFSET"):
                q.offset = self.expect_int()
        self.accept_op(";")
        if self.tok.kind != "eof":
            self.error("end of query")
        return q

    def parse_column(self):
        start = self.i
        expr = self.parse_expr()
        stop = self.i
        plain = stop - start == 1 and expr[0] == "name"
        alias = None
        if self.accept_kw("AS"):
            alias = self.expect_name()
        elif self.tok.kind == "name":
            alias = self.advance().value
        return expr, alias, self.text(start, stop), plain

    def parse_order_item(self):
        start = self.i
        expr = self.parse_expr()
        if self.i - start == 1 and self.tokens[start].kind == "int":
            item = ("pos", self.tokens[start].value)
        elif self.i - start == 1 and expr[0] == "name":
            item = ("ref", expr)
        else:
            item = ("expr", expr)
        descending = False
        if self.accept_kw("DESC"):
            descending = True
        else:
            self.accept_kw("ASC")
        return item, descending

    # -- expressions

    def parse_expr(self):
        left = self.parse_and()
        while self.accept_kw("OR"):
            left = ("or", left, self.parse_and())
        return left

    def parse_and(self):
        left = self.parse_not()
        while self.accept_kw("AND"):
            left = ("and", left, self.parse_not())
        return left

    def parse_not(self):
        if self.accept_kw("NOT"):
            return ("not", self.parse_not())
        return self.parse_comparison()

    def parse_comparison(self):
        left = self.parse_additive()
        while True:
            if self.at_op("=", "!=", "<>", "<", "<=", ">", ">="):
                op = self.advance().value
                if op == "<>":
                    op = "!="
                left = ("cmp", op, left, self.parse_additive())
            elif self.accept_kw("IS"):
                negated = bool(self.accept_kw("NOT"))
                self.expect_kw("NULL")
                left = ("isnull", left, negated)
            elif self.at_kw("NOT", "IN", "BETWEEN", "LIKE"):
                negated = bool(self.accept_kw("NOT"))
                if self.accept_kw("IN"):
                    self.expect_op("(")
                    items = [self.parse_expr()]
                    while self.accept_op(","):
                        items.append(self.parse_expr())
                    self.expect_op(")")
                    left = ("in", left, tuple(items), negated)
                elif self.accept_kw("BETWEEN"):
                    low = self.parse_additive()
                    self.expect_kw("AND")
                    high = self.parse_additive()
                    left = ("between", left, low, high, negated)
                elif self.accept_kw("LIKE"):
                    left = ("like", left, self.parse_additive(), negated)
                else:
                    self.error("IN, BETWEEN, or LIKE")
            else:
                return left

    def parse_additive(self):
        left = self.parse_multiplicative()
        while self.at_op("+", "-", "||"):
            op = self.advance().value
            left = ("bin", op, left, self.parse_multiplicative())
        return left

    def parse_multiplicative(self):
        left = self.parse_unary()
        while self.at_op("*", "/"):
            op = self.advance().value
            left = ("bin", op, left, self.parse_unary())
        return left

    def parse_unary(self):
        if self.accept_op("-"):
            return ("neg", self.parse_unary())
        return self.parse_primary()

    def parse_primary(self):
        tok = self.tok
        if tok.kind in ("int", "float", "str"):
            self.advance()
            return _lit(tok.value)
        if tok.kind == "kw" and tok.value in ("NULL", "TRUE", "FALSE"):
            self.advance()
            return _lit({"NULL": None, "TRUE": True, "FALSE": False}[tok.value])
        if tok.kind == "name":
            self.advance()
            if self.accept_op("("):
                return self.parse_call(tok.value)
            return ("name", tok.value)
        if self.accept_op("("):
            expr = self.parse_expr()
            self.expect_op(")")
            return expr
        self.error("an expression")

    def parse_call(self, name):
        name = name.upper()
        if name == "COUNT" and self.accept_op("*"):
            self.expect_op(")")
            return ("agg", name, None)
        args = []
        if not self.at_op(")"):
            args.append(self.parse_expr())
            while self.accept_op(","):
                args.append(self.parse_expr())
        self.expect_op(")")
        if name in AGGREGATES:
            if len(args) != 1:
                raise QueryError("%s takes exactly 1 argument" % name)
            return ("agg", name, args[0])
        if name not in SCALAR_ARITY:
            raise QueryError("unknown function %s" % name)
        low, high = SCALAR_ARITY[name]
        if len(args) < low or (high is not None and len(args) > high):
            if high is None:
                expected = "at least %d" % low
            elif low == high:
                expected = "exactly %d" % low
            else:
                expected = "%d to %d" % (low, high)
            raise QueryError("%s takes %s argument%s"
                             % (name, expected, "" if high == 1 else "s"))
        return ("func", name, tuple(args))


# ---------------------------------------------------------------------------
# Tables

_INT_RE = re.compile(r"-?[0-9]+")
_DECIMAL_RE = re.compile(r"-?[0-9]+\.[0-9]*|-?[0-9]*\.[0-9]+")


def _convert(field):
    if field == "":
        return None
    if _INT_RE.fullmatch(field):
        return int(field)
    if _DECIMAL_RE.fullmatch(field):
        return float(field)
    return field


def _load_table(directory, name):
    if not name or "/" in name or os.sep in name or name in (".", ".."):
        raise QueryError("invalid table name %r" % name)
    path = os.path.join(directory, name + ".csv")
    try:
        with open(path, newline="", encoding="utf-8-sig") as f:
            records = list(csv.reader(f))
    except FileNotFoundError:
        raise QueryError("unknown table %r" % name) from None
    except (OSError, UnicodeDecodeError, csv.Error) as e:
        raise QueryError("cannot read table %r: %s" % (name, e)) from None
    if not records:
        raise QueryError("table %r has no header" % name)
    header = records[0]
    width = len(header)
    rows = []
    for line_number, record in enumerate(records[1:], start=2):
        if not record:
            continue  # blank line
        if len(record) > width:
            raise QueryError("table %r: row %d has more fields than the header"
                             % (name, line_number))
        record = record + [""] * (width - len(record))
        rows.append([_convert(field) for field in record])
    return header, rows


# ---------------------------------------------------------------------------
# Name resolution and static checks


def _contains_aggregate(node):
    if node[0] == "agg":
        return True
    return any(_contains_aggregate(child) for child in _children(node))


def _children(node):
    tag = node[0]
    if tag in ("lit", "name", "col"):
        return ()
    if tag == "agg":
        return () if node[2] is None else (node[2],)
    if tag in ("neg", "not", "isnull"):
        return (node[1],)
    if tag in ("and", "or"):
        return (node[1], node[2])
    if tag in ("bin", "cmp"):
        return (node[2], node[3])
    if tag == "in":
        return (node[1],) + node[2]
    if tag == "between":
        return (node[1], node[2], node[3])
    if tag == "like":
        return (node[1], node[2])
    if tag == "func":
        return node[2]
    raise AssertionError(tag)


def _resolve(node, columns, in_aggregate=False):
    """Replace names with column indexes, checking aggregate nesting."""
    tag = node[0]
    if tag == "lit":
        return node
    if tag == "name":
        index = columns.get(node[1].lower())
        if index is None:
            raise QueryError("unknown column %r" % node[1])
        return ("col", index)
    if tag == "agg":
        if in_aggregate:
            raise QueryError("aggregate functions can't be nested")
        if node[2] is None:
            return node
        return ("agg", node[1], _resolve(node[2], columns, True))

    def r(child):
        return _resolve(child, columns, in_aggregate)

    if tag in ("neg", "not"):
        return (tag, r(node[1]))
    if tag in ("and", "or"):
        return (tag, r(node[1]), r(node[2]))
    if tag in ("bin", "cmp"):
        return (tag, node[1], r(node[2]), r(node[3]))
    if tag == "isnull":
        return (tag, r(node[1]), node[2])
    if tag == "in":
        return (tag, r(node[1]), tuple(r(item) for item in node[2]), node[3])
    if tag == "between":
        return (tag, r(node[1]), r(node[2]), r(node[3]), node[4])
    if tag == "like":
        return (tag, r(node[1]), r(node[2]), node[3])
    if tag == "func":
        return (tag, node[1], tuple(r(arg) for arg in node[2]))
    raise AssertionError(tag)


def _check_grouped(node, group_exprs, header):
    """Check that columns outside aggregates are GROUP BY expressions."""
    if node in group_exprs or node[0] == "agg":
        return
    if node[0] == "col":
        raise QueryError("column %r must appear in GROUP BY or be used in an "
                         "aggregate function" % header[node[1]])
    for child in _children(node):
        _check_grouped(child, group_exprs, header)


# ---------------------------------------------------------------------------
# Evaluation


def _kind(value):
    if isinstance(value, bool):
        return "boolean"
    if isinstance(value, (int, float)):
        return "number"
    return "string"


def _describe(value):
    return "%s %r" % (_kind(value), value)


def _compare(a, b):
    """Compare two non-NULL values, returning -1, 0, or 1."""
    if _kind(a) != _kind(b):
        raise QueryError("can't compare %s with %s"
                         % (_describe(a), _describe(b)))
    return (a > b) - (a < b)


def _sort_compare(a, b):
    """Like ``_compare`` but with NULL before everything."""
    if a is None or b is None:
        return (a is not None) - (b is not None)
    return _compare(a, b)


def _key(value):
    """A hashable key under which equal SQL values are equal."""
    if value is None:
        return ("null",)
    return (_kind(value), value)


def _check_bool(value, what):
    if value is not None and not isinstance(value, bool):
        raise QueryError("%s needs a boolean, got %s" % (what, _describe(value)))
    return value


def _check_number(value, what):
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        raise QueryError("%s needs a number, got %s" % (what, _describe(value)))
    return value


def _check_string(value, what):
    if not isinstance(value, str):
        raise QueryError("%s needs a string, got %s" % (what, _describe(value)))
    return value


def _text(value):
    if isinstance(value, bool):
        return "true" if value else "false"
    return str(value)


_CMP = {
    "=": lambda c: c == 0, "!=": lambda c: c != 0,
    "<": lambda c: c < 0, "<=": lambda c: c <= 0,
    ">": lambda c: c > 0, ">=": lambda c: c >= 0,
}


def _arith(op, a, b):
    if op == "||":
        return _text(a) + _text(b)
    _check_number(a, "'%s'" % op)
    _check_number(b, "'%s'" % op)
    try:
        if op == "+":
            return a + b
        if op == "-":
            return a - b
        if op == "*":
            return a * b
        if b == 0:
            return None
        return a / b
    except OverflowError:
        raise QueryError("numeric overflow in '%s'" % op) from None


@functools.lru_cache(maxsize=256)
def _like_regex(pattern):
    parts = []
    for ch in pattern:
        if ch == "%":
            parts.append(".*")
        elif ch == "_":
            parts.append(".")
        else:
            parts.append(re.escape(ch))
    return re.compile("".join(parts), re.DOTALL)


def _round(x, places):
    _check_number(x, "ROUND")
    if places is not None:
        if isinstance(places, bool) or not isinstance(places, int):
            raise QueryError("ROUND needs an integer number of places, got %s"
                             % _describe(places))
    if isinstance(x, float) and not math.isfinite(x):
        if places is None:
            raise QueryError("can't round %r to an integer" % x)
        return x
    with decimal.localcontext() as ctx:
        ctx.prec = 1000
        ctx.rounding = decimal.ROUND_HALF_UP  # halves away from zero
        d = decimal.Decimal(repr(x) if isinstance(x, float) else x)
        if places is None:
            return int(d.quantize(decimal.Decimal(1)))
        if places > 400:
            return float(x)
        if places < -400:
            return 0.0
        return float(d.quantize(decimal.Decimal(1).scaleb(-places)))


def _call(name, args):
    if any(value is None for value in args):
        return None
    x = args[0]
    if name == "LOWER":
        return _check_string(x, name).lower()
    if name == "UPPER":
        return _check_string(x, name).upper()
    if name == "LENGTH":
        return len(_check_string(x, name))
    if name == "ABS":
        return abs(_check_number(x, name))
    if name == "ROUND":
        return _round(x, args[1] if len(args) > 1 else None)
    raise AssertionError(name)


def _aggregate(name, arg, rows):
    if arg is None:
        return len(rows)
    values = [v for v in (_eval(arg, row, None) for row in rows)
              if v is not None]
    if name == "COUNT":
        return len(values)
    if not values:
        return None
    if name in ("SUM", "AVG"):
        for v in values:
            _check_number(v, name)
        try:
            total = sum(values)
            return total / len(values) if name == "AVG" else total
        except OverflowError:
            raise QueryError("numeric overflow in %s" % name) from None
    best = values[0]
    for v in values[1:]:
        c = _compare(v, best)
        if (c < 0) if name == "MIN" else (c > 0):
            best = v
    return best


class _Group:
    def __init__(self, rows, values):
        self.rows = rows
        self.values = values  # GROUP BY expression -> its value


def _eval(node, row, group):
    """Evaluate ``node`` on ``row``, or on ``group`` in a grouped query."""
    if group is not None:
        if node in group.values:
            return group.values[node]
        if node[0] == "agg":
            return _aggregate(node[1], node[2], group.rows)
    tag = node[0]
    if tag == "lit":
        return node[2]
    if tag == "col":
        return row[node[1]]
    if tag == "and" or tag == "or":
        what = tag.upper()
        a = _check_bool(_eval(node[1], row, group), what)
        short = tag == "or"  # TRUE OR x is TRUE; FALSE AND x is FALSE
        if a is short:
            return a
        b = _check_bool(_eval(node[2], row, group), what)
        if b is short:
            return b
        if a is None or b is None:
            return None
        return not short
    if tag == "not":
        a = _check_bool(_eval(node[1], row, group), "NOT")
        return None if a is None else not a
    if tag == "isnull":
        a = _eval(node[1], row, group)
        return (a is not None) if node[2] else (a is None)
    if tag == "func" and node[1] == "COALESCE":
        for arg in node[2]:
            value = _eval(arg, row, group)
            if value is not None:
                return value
        return None
    if tag == "in":
        x = _eval(node[1], row, group)
        saw_null = x is None
        for item in node[2]:
            value = _eval(item, row, group)
            if value is None:
                saw_null = True
            elif x is not None and _compare(x, value) == 0:
                return not node[3]
        if saw_null:
            return None
        return node[3]

    if tag == "neg":
        a = _eval(node[1], row, group)
        return None if a is None else -_check_number(a, "unary '-'")
    if tag == "bin":
        a = _eval(node[2], row, group)
        b = _eval(node[3], row, group)
        if a is None or b is None:
            return None
        return _arith(node[1], a, b)
    if tag == "cmp":
        a = _eval(node[2], row, group)
        b = _eval(node[3], row, group)
        if a is None or b is None:
            return None
        return _CMP[node[1]](_compare(a, b))
    if tag == "between":
        x = _eval(node[1], row, group)
        low = _eval(node[2], row, group)
        high = _eval(node[3], row, group)
        if x is None:
            return None
        lower_ok = None if low is None else _compare(low, x) <= 0
        upper_ok = None if high is None else _compare(x, high) <= 0
        if lower_ok is False or upper_ok is False:
            result = False
        elif lower_ok is None or upper_ok is None:
            return None
        else:
            result = True
        return result != node[4]
    if tag == "like":
        x = _eval(node[1], row, group)
        pattern = _eval(node[2], row, group)
        if x is None or pattern is None:
            return None
        _check_string(x, "LIKE")
        _check_string(pattern, "LIKE")
        return bool(_like_regex(pattern).fullmatch(x)) != node[3]
    if tag == "func":
        return _call(node[1], [_eval(arg, row, group) for arg in node[2]])
    if tag == "agg":
        raise AssertionError("aggregate outside a grouped query")
    raise AssertionError(tag)


def _condition(node, row, group, clause):
    return _check_bool(_eval(node, row, group), clause) is True


# ---------------------------------------------------------------------------
# Execution


def _execute(q, directory):
    header, rows = _load_table(directory, q.table)
    names = {}
    for index, name in enumerate(header):
        names.setdefault(name.lower(), index)

    def resolve(node, clause=None):
        node = _resolve(node, names)
        if clause and _contains_aggregate(node):
            raise QueryError("aggregate functions can't be used in %s" % clause)
        return node

    # Output columns: (expression, name).
    if q.columns is None:
        columns = [(("col", i), name) for i, name in enumerate(header)]
    else:
        columns = []
        for expr, alias, text, plain in q.columns:
            node = resolve(expr)
            if alias is not None:
                name = alias
            elif plain:
                name = header[node[1]]
            else:
                name = text
            columns.append((node, name))
    output_names = [name.lower() for _, name in columns]

    where = resolve(q.where, "WHERE") if q.where is not None else None
    group_by = [resolve(expr, "GROUP BY") for expr in q.group_by]
    having = resolve(q.having) if q.having is not None else None

    # ORDER BY items: ("out", column index) or ("expr", expression).
    order_by = []
    for (kind, value), descending in q.order_by:
        if kind == "pos":
            if not 1 <= value <= len(columns):
                raise QueryError("ORDER BY position %d is not in the select "
                                 "list" % value)
            order_by.append((("out", value - 1), descending))
        elif kind == "ref" and value[1].lower() in output_names:
            index = output_names.index(value[1].lower())
            order_by.append((("out", index), descending))
        else:
            order_by.append((("expr", resolve(value)), descending))

    order_exprs = [v for (k, v), _ in order_by if k == "expr"]
    grouped = bool(group_by) or any(
        _contains_aggregate(node)
        for node in [c for c, _ in columns] + [having] + order_exprs
        if node is not None)

    if grouped:
        group_set = set(group_by)
        for node in [c for c, _ in columns] + [having] + order_exprs:
            if node is not None:
                _check_grouped(node, group_set, header)

    if where is not None:
        rows = [row for row in rows if _condition(where, row, None, "WHERE")]

    # Each unit is (row, group): a row of an ungrouped query or a group.
    if grouped:
        if group_by:
            groups = {}
            for row in rows:
                values = [_eval(expr, row, None) for expr in group_by]
                key = tuple(_key(v) for v in values)
                if key not in groups:
                    groups[key] = _Group([], dict(zip(group_by, values)))
                groups[key].rows.append(row)
            units = [(g.rows[0], g) for g in groups.values()]
        else:
            units = [(None, _Group(rows, {}))]
    else:
        units = [(row, None) for row in rows]

    if having is not None:
        units = [(row, group) for row, group in units
                 if _condition(having, row, group, "HAVING")]

    results = []
    for row, group in units:
        out = tuple(_eval(node, row, group) for node, _ in columns)
        keys = [out[v] if k == "out" else _eval(v, row, group)
                for (k, v), _ in order_by]
        results.append((out, keys))

    if q.distinct:
        seen = set()
        unique = []
        for out, keys in results:
            key = tuple(_key(v) for v in out)
            if key not in seen:
                seen.add(key)
                unique.append((out, keys))
        results = unique

    if order_by:
        directions = [descending for _, descending in order_by]

        def compare(a, b):
            for x, y, descending in zip(a[1], b[1], directions):
                c = _sort_compare(x, y)
                if c:
                    return -c if descending else c
            return 0

        results.sort(key=functools.cmp_to_key(compare))

    end = None if q.limit is None else q.offset + q.limit
    results = results[q.offset:end]
    return Result([name for _, name in columns], [out for out, _ in results])

